"use strict";(self.webpackChunkai_pack_docs=self.webpackChunkai_pack_docs||[]).push([["1918"],{3892(n,e,t){t.r(e),t.d(e,{metadata:()=>i,default:()=>u,frontMatter:()=>a,contentTitle:()=>o,toc:()=>l,assets:()=>c});var i=JSON.parse('{"id":"gates/verification","title":"Verification Gates","description":"Version: 1.0.0","source":"@site/../content/gates/30-verification.md","sourceDirName":"gates","slug":"/gates/verification","permalink":"/ai-pack/docs/gates/verification","draft":false,"unlisted":false,"editUrl":"https://github.com/Cortexa-LLC/ai-pack/tree/main/docs/../content/gates/30-verification.md","tags":[],"version":"current","sidebarPosition":9,"frontMatter":{"sidebar_position":9,"title":"Verification Gates"},"sidebar":"tutorialSidebar","previous":{"title":"Execution Strategy","permalink":"/ai-pack/docs/gates/execution-strategy"},"next":{"title":"Code Quality Review","permalink":"/ai-pack/docs/gates/code-quality-review"}}'),r=t(4848),s=t(8453);let a={sidebar_position:9,title:"Verification Gates"},o="Verification Gates",c={},l=[{value:"Overview",id:"overview",level:2},{value:"Verification Stages",id:"verification-stages",level:2},{value:"Pre-Implementation Checks",id:"pre-implementation-checks",level:2},{value:"1. Requirements Clarity",id:"1-requirements-clarity",level:3}];function d(n){let e={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...n.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(e.header,{children:(0,r.jsx)(e.h1,{id:"verification-gates",children:"Verification Gates"})}),"\n",(0,r.jsxs)(e.p,{children:[(0,r.jsx)(e.strong,{children:"Version:"})," 1.0.0\n",(0,r.jsx)(e.strong,{children:"Last Updated:"})," 2026-01-07"]}),"\n",(0,r.jsx)(e.h2,{id:"overview",children:"Overview"}),"\n",(0,r.jsx)(e.p,{children:"Verification gates define quality checks and validation requirements that must be satisfied at different stages of the workflow. These gates ensure work meets standards before progressing."}),"\n",(0,r.jsx)(e.h2,{id:"verification-stages",children:"Verification Stages"}),"\n",(0,r.jsx)(e.p,{children:"Verification occurs at three critical stages:"}),"\n",(0,r.jsxs)(e.ol,{children:["\n",(0,r.jsxs)(e.li,{children:[(0,r.jsx)(e.strong,{children:"Pre-implementation"})," - Before starting work"]}),"\n",(0,r.jsxs)(e.li,{children:[(0,r.jsx)(e.strong,{children:"Mid-implementation"})," - During development"]}),"\n",(0,r.jsxs)(e.li,{children:[(0,r.jsx)(e.strong,{children:"Post-implementation"})," - Before completion"]}),"\n"]}),"\n",(0,r.jsx)(e.hr,{}),"\n",(0,r.jsx)(e.h2,{id:"pre-implementation-checks",children:"Pre-Implementation Checks"}),"\n",(0,r.jsxs)(e.p,{children:[(0,r.jsx)(e.strong,{children:"Purpose:"})," Ensure readiness before beginning work."]}),"\n",(0,r.jsx)(e.h3,{id:"1-requirements-clarity",children:"1. Requirements Clarity"}),"\n",(0,r.jsxs)(e.p,{children:[(0,r.jsx)(e.strong,{children:"Checkpoint:"})," Are requirements clear and unambiguous?"]}),"\n",(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"Verification:"})}),"\n",(0,r.jsx)(e.pre,{children:(0,r.jsx)(e.code,{className:"language-text",children:'\u2713 Task objectives are well-defined\n\u2713 Success criteria are measurable\n\u2713 Constraints are understood\n\u2713 Acceptance criteria are clear\n\u2713 Ambiguities have been resolved\n```text\n\n**Action if not met:**\n```text\nIF requirements unclear THEN\n  use AskUserQuestion tool\n  clarify ambiguities\n  document clarifications\n  wait for confirmation\n  THEN proceed\nEND IF\n```text\n\n---\n\n### 2. Context Understanding\n\n**Checkpoint:** Do we understand the codebase context?\n\n**Verification:**\n```text\n\u2713 Relevant code has been read\n\u2713 Existing patterns identified\n\u2713 Dependencies understood\n\u2713 Architecture comprehended\n\u2713 Test coverage assessed\n```text\n\n**Required Activities:**\n```text\nBEFORE implementation:\n  read relevant files\n  identify patterns to follow\n  understand dependencies\n  review existing tests\n  check architecture alignment\nEND BEFORE\n```text\n\n---\n\n### 3. Approach Validation\n\n**Checkpoint:** Is the implementation approach sound?\n\n**Verification:**\n```text\n\u2713 Approach aligns with requirements\n\u2713 Follows existing patterns\n\u2713 Considers edge cases\n\u2713 Has testing strategy\n\u2713 Has rollback plan\n```text\n\n**For non-trivial tasks:**\n```text\nIF task is non-trivial THEN\n  enter plan mode\n  create implementation plan\n  present plan to user\n  get approval\n  THEN implement\nEND IF\n```text\n\n---\n\n## Mid-Implementation Validation\n\n**Purpose:** Ensure quality during development.\n\n### 4. Incremental Testing\n\n**Checkpoint:** Tests pass at each step.\n\n**Verification:**\n```text\nAFTER each significant change:\n  run relevant tests\n  \u2713 All tests pass\n  \u2713 No new failures introduced\n  \u2713 Test coverage maintained\n  IF tests fail THEN\n    fix immediately\n    don\'t proceed until green\n  END IF\nEND AFTER\n```text\n\n**TDD Cycle:**\n```text\n1. Write failing test (RED)\n2. Write minimal code to pass (GREEN)\n3. Refactor while keeping tests green (REFACTOR)\n4. Repeat\n```text\n\n---\n\n### 5. Standards Compliance\n\n**Checkpoint:** Code follows established standards.\n\n**Verification:**\n```text\n\u2713 Formatting correct (spaces, not tabs)\n\u2713 Naming conventions followed\n\u2713 Language-specific guidelines met\n\u2713 No code smells introduced\n\u2713 Design principles upheld\n```text\n\n**Continuous Checks:**\n```text\nDURING development:\n  follow formatting standards\n  use consistent naming\n  apply SOLID principles\n  avoid code smells\n  maintain simplicity (YAGNI)\nEND DURING\n```text\n\n---\n\n### 6. Pattern Consistency\n\n**Checkpoint:** New code follows existing patterns.\n\n**Verification:**\n```text\n\u2713 Error handling matches existing code\n\u2713 Logging follows project conventions\n\u2713 API design consistent\n\u2713 Test structure similar\n\u2713 Documentation style maintained\n```text\n\n**Pattern Matching:**\n```text\nWHEN writing new code:\n  identify similar existing code\n  follow established patterns\n  maintain consistency\n  IF deviation necessary THEN\n    document rationale\n    get user approval\n  END IF\nEND WHEN\n```text\n\n---\n\n## Post-Implementation Verification\n\n**Purpose:** Confirm work is complete and meets requirements.\n\n### 7. Comprehensive Testing\n\n**Checkpoint:** All tests pass, coverage meets target.\n\n**Verification:**\n```text\n\u2713 All unit tests pass\n\u2713 All integration tests pass\n\u2713 All acceptance tests pass\n\u2713 Code coverage: 80-90%\n\u2713 No flaky tests\n\u2713 Test execution time reasonable\n```text\n\n**Test Execution:**\n```text\nRUN full test suite:\n  unit tests\n  integration tests\n  acceptance tests\n\nVERIFY results:\n  \u2713 0 failures (zero tolerance)\n  \u2713 Coverage in target range\n  \u2713 No skipped tests (unless documented)\n\nIF any test fails THEN\n  STOP: do not proceed\n  fix failing tests\n  re-run full suite\n  THEN continue\nEND IF\n```text\n\n---\n\n### 8. Build Verification (BLOCKING - ZERO WARNINGS REQUIRED)\n\n**Checkpoint:** Project builds successfully with **ZERO WARNINGS**.\n\n**\u26A0\uFE0F CRITICAL: Code MUST compile/build with ZERO WARNINGS. Warnings are treated as errors.**\n\n**Verification:**\n```text\n\u2713 Clean build succeeds\n\u2713 No compilation errors\n\u2713 No compilation warnings (BLOCKING)\n\u2713 No linking errors\n\u2713 No linting errors\n\u2713 No type errors\n\u2713 No style violations\n```text\n\n**MANDATORY Build Process:**\n```text\nRUN build WITH WARNINGS AS ERRORS:\n\n  # C/C++ Projects\n  IF C++ project THEN\n    # Treat all warnings as errors\n    cmake -DCMAKE_CXX_FLAGS="-Werror -Wall -Wextra" ..\n    make\n    # OR\n    g++ -Werror -Wall -Wextra *.cpp\n    \u2713 MUST show "0 warnings"\n  END IF\n\n  # C# Projects\n  IF C# project THEN\n    # Treat warnings as errors (MANDATORY)\n    dotnet build /warnaserror\n    # OR verify in .csproj:\n    # <TreatWarningsAsErrors>true</TreatWarningsAsErrors>\n    \u2713 MUST show "0 Warning(s)"\n  END IF\n\n  # Java Projects\n  IF Java project THEN\n    # Maven: treat warnings as errors\n    mvn clean compile -Dmaven.compiler.showWarnings=true -Werror\n    # Gradle: enable warnings as errors\n    ./gradlew build -Pwarnings-as-errors\n    \u2713 MUST show "BUILD SUCCESS" with 0 warnings\n  END IF\n\n  # JavaScript/TypeScript Projects\n  IF JS/TS project THEN\n    # TypeScript: strict mode\n    tsc --noEmitOnError --strict\n    # ESLint: fail on warnings\n    eslint . --max-warnings 0\n    \u2713 MUST show "0 problems"\n  END IF\n\n  # Python Projects\n  IF Python project THEN\n    # Flake8: fail on any issues\n    flake8 . --count --show-source --statistics\n    # mypy: strict type checking\n    mypy . --strict --warn-unreachable\n    \u2713 MUST show "0 errors", "0 warnings"\n  END IF\n\n  # Go Projects\n  IF Go project THEN\n    # Go: vet checks\n    go vet ./...\n    # golangci-lint: strict\n    golangci-lint run --max-issues-per-linter 0 --max-same-issues 0\n    \u2713 MUST show "0 issues"\n  END IF\n\n  # Rust Projects\n  IF Rust project THEN\n    # Cargo: deny warnings\n    cargo build --release\n    cargo clippy -- -D warnings\n    \u2713 MUST show "0 warnings"\n  END IF\n\nEND RUN\n\n**ENFORCEMENT:**\n```text\nIF any warnings detected THEN\n  STOP immediately\n  BLOCK completion\n  LIST all warnings\n  FIX all warnings\n  RE-RUN build\n  ONLY proceed when: 0 warnings\nEND IF\n```text\n\n**Pre-Commit Checklist (MANDATORY):**\n```text\nBEFORE committing code:\n  \u2713 Run build with warnings-as-errors flag\n  \u2713 Verify output shows "0 warnings"\n  \u2713 Run linter/formatter\n  \u2713 Fix ALL issues\n  \u2713 Re-run build to confirm\n  \u2713 THEN commit\n```text\n\n---\n\n### 9. Requirement Satisfaction\n\n**Checkpoint:** All requirements have been met.\n\n**Verification:**\n```text\nFOR each requirement:\n  \u2713 Implemented as specified\n  \u2713 Tests verify behavior\n  \u2713 Edge cases handled\n  \u2713 Error cases handled\n  \u2713 Documented if needed\nEND FOR\n```text\n\n**Acceptance Criteria Check:**\n```text\nREVIEW acceptance criteria from contract:\n  \u2713 All criteria met\n  \u2713 Success metrics achieved\n  \u2713 Constraints respected\n  \u2713 User expectations satisfied\n\nIF criteria not met THEN\n  identify gaps\n  implement missing pieces\n  re-verify\nEND IF\n```text\n\n---\n\n### 10. Integration Verification\n\n**Checkpoint:** Changes integrate correctly with existing system.\n\n**Verification:**\n```text\n\u2713 No breaking changes to public APIs\n\u2713 Backward compatibility maintained (if required)\n\u2713 Dependencies updated correctly\n\u2713 Configuration changes documented\n\u2713 Migration path provided (if needed)\n```text\n\n**Integration Tests:**\n```text\nRUN integration checks:\n  test with existing components\n  verify no regressions\n  check performance impact\n  validate error handling\n\nIF integration issues THEN\n  fix integration problems\n  update dependent code\n  re-test integration\nEND IF\n```text\n\n---\n\n## Documentation Requirements\n\n### 11. Code Documentation\n\n**Checkpoint:** Code is adequately documented.\n\n**Verification:**\n```text\n\u2713 Public APIs documented\n\u2713 Complex logic explained\n\u2713 Non-obvious decisions documented\n\u2713 Examples provided (if helpful)\n\u2713 Comments accurate and current\n```text\n\n**Documentation Standards:**\n```text\nDocument:\n  \u2705 Public interfaces and APIs\n  \u2705 Complex algorithms\n  \u2705 Non-obvious design decisions\n  \u2705 Deviation from standards (with rationale)\n\nDon\'t document:\n  \u274C Obvious code\n  \u274C Self-explanatory functions\n  \u274C Code that doesn\'t need explanation\n```text\n\n---\n\n### 12. Change Documentation\n\n**Checkpoint:** Changes are properly documented.\n\n**Verification:**\n```text\n\u2713 Commit messages clear and descriptive\n\u2713 Work log updated (in .ai/tasks/)\n\u2713 Breaking changes documented\n\u2713 Migration guide provided (if needed)\n\u2713 Changelog updated (if project has one)\n```text\n\n**Commit Message Quality:**\n```text\nCommit should include:\n- Type (feat/fix/refactor/test/docs)\n- Short summary (50 chars max)\n- Detailed description (if needed)\n- References to issues (if applicable)\n- Co-authored-by attribution\n```text\n\n---\n\n## Task State Management\n\n### 13. Task Packet Updates\n\n**Checkpoint:** Task packet in `.ai/tasks/` is current.\n\n**Verification:**\n```text\n\u2713 Contract established (00-contract.md)\n\u2713 Plan documented (10-plan.md)\n\u2713 Work log updated (20-work-log.md)\n\u2713 Review completed (30-review.md)\n\u2713 Acceptance signed off (40-acceptance.md)\n```text\n\n**Update Requirements:**\n```text\nDURING task execution:\n  initialize task packet\n  update work log incrementally\n  document decisions\n  track issues and resolutions\n\nUPON completion:\n  finalize work log\n  conduct review\n  complete acceptance checklist\nEND DURING\n```text\n\n---\n\n## Specialized Verifications\n\n### For Refactoring\n\n**Additional Checks:**\n```text\n\u2713 Behavior unchanged (tests prove it)\n\u2713 Test suite unchanged (unless improving tests)\n\u2713 Performance not degraded\n\u2713 All tests still pass\n\u2713 Code quality improved\n```text\n\n### For Bug Fixes\n\n**Additional Checks:**\n```text\n\u2713 Bug reproduced first\n\u2713 Test added for bug\n\u2713 Test fails before fix\n\u2713 Test passes after fix\n\u2713 Root cause understood and documented\n\u2713 Similar bugs checked for\n```text\n\n### For New Features\n\n**Additional Checks:**\n```text\n\u2713 Feature complete (not partial)\n\u2713 User documentation updated\n\u2713 Tests cover happy path + edge cases\n\u2713 Error handling comprehensive\n\u2713 Performance acceptable\n\u2713 Security considered\n```text\n\n### For Performance Optimization\n\n**Additional Checks:**\n```text\n\u2713 Baseline metrics captured\n\u2713 Improvement measured\n\u2713 No functionality broken\n\u2713 Trade-offs understood\n\u2713 Performance gains documented\n```text\n\n---\n\n## Rollback Triggers\n\n**When to rollback:**\n\n```text\nROLLBACK if:\n  \u274C Tests fail and can\'t be fixed quickly\n  \u274C Build breaks\n  \u274C Performance degrades significantly\n  \u274C Security vulnerability introduced\n  \u274C Breaking change not approved\n  \u274C Requirements misunderstood\n```text\n\n**Rollback Process:**\n```text\n1. Stop current work\n2. Revert changes (git revert/reset)\n3. Verify system restored\n4. Analyze what went wrong\n5. Revise approach\n6. Get user approval\n7. Re-attempt correctly\n```text\n\n---\n\n## Quality Metrics\n\n### Target Metrics\n\n```text\nTest Coverage:     80-90%\nTest Pass Rate:    100% (zero tolerance for failures)\nBuild Success:     100%\nCode Review:       No critical findings\nStandards:         100% compliance\nDocumentation:     All public APIs documented\n```text\n\n### Measurement\n\n```text\nMEASURE quality:\n  run coverage tool \u2192 verify 80-90%\n  run test suite \u2192 verify 100% pass\n  run linter \u2192 verify 0 errors\n  run security scan \u2192 verify no criticals\n  review code \u2192 verify standards met\nEND MEASURE\n```text\n\n---\n\n## Integration\n\nVerification gates integrate with:\n- **[Global Gates](00-global-gates.md)** - Overall quality requirements\n- **[Persistence Gates](10-persistence.md)** - File operation validation\n- **[Tool Policy](20-tool-policy.md)** - Tool result verification\n- **[Workflows](../workflows/)** - Stage-specific verification\n- **[Task Packets](../templates/task-packet/)** - Progress tracking\n\n---\n\n## Continuous Verification\n\n**Philosophy:** Verify continuously, not just at end.\n\n```text\nPre-implementation:  Verify readiness\nDuring implementation: Verify incrementally\nPost-implementation: Verify completion\nBefore user handoff:  Verify acceptance criteria\n```text\n\n**Benefits:**\n- Catch issues early\n- Maintain quality throughout\n- Reduce rework\n- Build confidence incrementally\n- Enable safe, incremental progress\n\n---\n\n**Last reviewed:** 2026-01-07\n**Next review:** Quarterly or when verification processes need refinement\n'})})]})}function u(n={}){let{wrapper:e}={...(0,s.R)(),...n.components};return e?(0,r.jsx)(e,{...n,children:(0,r.jsx)(d,{...n})}):d(n)}},8453(n,e,t){t.d(e,{R:()=>a,x:()=>o});var i=t(6540);let r={},s=i.createContext(r);function a(n){let e=i.useContext(s);return i.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function o(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(r):n.components||r:a(n.components),i.createElement(s.Provider,{value:e},n.children)}}}]);